import {useRef,useState} from 'react';

export const stateDimensions=['EXPOSURE','ACCESS','PERCEPTION','ATTENTION','EXAMINATION','COMPREHENSION','RECALL','SUSPICION','INCLINATION','DOUBT','BELIEF','SUSPENDED_JUDGMENT','CLAIMED_KNOWLEDGE','PERCEIVED_KNOWLEDGE','EVIDENCE_SUPPORTED_KNOWLEDGE'];
export const orientationDimensions=['INTEREST','CURIOSITY','INDIFFERENCE','AVERSION','LIMITED_INQUIRY','DENIABILITY_PRESERVATION','DELEGATED_KNOWING','DOCUMENTATION_AVOIDANCE'];
export const trustDimensions=['TRUST_COMPETENCE','TRUST_CONFIDENTIALITY','TRUST_TRUTHFULNESS'];
export const relationalDimensions=[...trustDimensions,'LOYALTY'];
export const protectiveMotiveDimensions=['EGO_PROTECTION','IDENTITY_PROTECTION'];
export const autonomyDimensions=['AUTONOMY_DECIDE','AUTONOMY_REFUSE','AUTONOMY_DISAGREE','AUTONOMY_EXIT','AUTONOMY_SEEK_REVIEW','AUTONOMY_ACQUIRE_INFORMATION','AUTONOMY_REVISE_COMMITMENTS'];
export const contextualPressureDimensions=['INCENTIVE','PRESSURE','COMMUNICATED_THREAT','ADVERSE_CONDITION','COERCION','CONSTRAINT','DEPENDENCY','LEVERAGE'];
export const threatFacetDimensions=['THREAT_CAPABILITY','THREAT_INTENT','THREAT_PERCEIVED_CREDIBILITY','THREAT_OUTCOME'];
export const contextualVulnerabilityDimensions=['VULNERABILITY','COERCION_SUSCEPTIBILITY','COMPLIANCE','CONSENT','SUBMISSION'];
export const influenceDimensions=['INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS'];
export const influenceTargets=['BELIEF','ATTENTION','INTEREST','CURIOSITY','TRUST','ACCEPTANCE','INTERPRETATION','INVESTIGATION_PRIORITY','WILLINGNESS_TO_EXAMINE'];
export const asymmetryDimensions=['ASYMMETRY_INFORMATION','ASYMMETRY_ACCESS','ASYMMETRY_UNDERSTANDING','ASYMMETRY_META_KNOWLEDGE','ASYMMETRY_INFLUENCE'];
export const powerDimensions=['EPISTEMIC_POWER','FORMAL_AUTHORITY',...asymmetryDimensions];
const pressureDimensions=[...contextualPressureDimensions,...threatFacetDimensions,...contextualVulnerabilityDimensions];
const counterpartyDimensions=[...pressureDimensions,...influenceDimensions,...powerDimensions];
const issuerRequiredDimensions=['THREAT_CAPABILITY','THREAT_INTENT','INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT',...asymmetryDimensions];
const objectOnlyDimensions=[...protectiveMotiveDimensions,...autonomyDimensions,...counterpartyDimensions];
const orientationScopes=['IMMEDIATE_REACTION','PERSISTENT_DISPOSITION'];
const judgments=['INDICATED','NOT_INDICATED','UNKNOWN','CONTESTED'];
const empty={subject_actor_id:'',target_object_id:'',target_state_event_id:null,target_actor_id:null,counterparty_actor_id:null,influence_target:null,dimension:'',judgment:'',context:'',temporal_scope:'',orientation_scope:null,orientation_goal:null,rationale:'',basis_evidence_id:'',revises_event_id:null};
const label=value=>value.replaceAll('_',' ').toLowerCase();
export function stateRequest(draft,actors,nodes,evidence,events) {
  if(!actors.some(a=>a.actor_id===draft.subject_actor_id)||[draft.target_object_id,draft.target_state_event_id,draft.target_actor_id].filter(Boolean).length!==1)throw new Error('Select a visible actor and exactly one target.');
  if(draft.target_object_id&&!nodes.some(n=>n.object_id===draft.target_object_id)||draft.target_state_event_id&&!events.some(e=>e.event_id===draft.target_state_event_id)||draft.target_actor_id&&!actors.some(a=>a.actor_id===draft.target_actor_id))throw new Error('Select a visible target.');
  const trust=trustDimensions.includes(draft.dimension),relational=relationalDimensions.includes(draft.dimension);
  if(trust&&!draft.target_actor_id||draft.dimension==='LOYALTY'&&draft.target_state_event_id||!relational&&draft.target_actor_id)throw new Error('Trust requires a directed actor target; loyalty allows an actor or principle object.');
  const orientation=orientationDimensions.includes(draft.dimension);
  const objectOnly=objectOnlyDimensions.includes(draft.dimension);
  if(draft.counterparty_actor_id&&(!counterpartyDimensions.includes(draft.dimension)||draft.counterparty_actor_id===draft.subject_actor_id||!actors.some(a=>a.actor_id===draft.counterparty_actor_id)))throw new Error('Select a distinct, registered counterparty for this contextual judgment.');
  if(issuerRequiredDimensions.includes(draft.dimension)&&!draft.counterparty_actor_id)throw new Error('Identify the required distinct counterparty for this judgment.');
  if(influenceDimensions.includes(draft.dimension)?!influenceTargets.includes(draft.influence_target):!!draft.influence_target)throw new Error('An influence judgment requires an explicit epistemic target, and other dimensions do not allow one.');
  if(objectOnly&&!draft.target_object_id)throw new Error('This contextual judgment requires a Situation object.');
  if(!orientation&&!relational&&!objectOnly&&!stateDimensions.includes(draft.dimension)||!judgments.includes(draft.judgment)&&!(trust&&draft.judgment==='DISTRUST_INDICATED'))throw new Error('Choose an independent dimension and judgment.');
  if(orientation&&(!orientationScopes.includes(draft.orientation_scope)||!draft.orientation_goal?.trim()||draft.orientation_goal.trim().length>2048))throw new Error('An orientation requires a scope and explicit goal.');
  if(!orientation&&(draft.orientation_scope||draft.orientation_goal))throw new Error('An ordinary state is not an orientation.');
  for(const [field,max] of [['context',2048],['temporal_scope',2048],['rationale',4096]])if(!draft[field].trim()||draft[field].trim().length>max)throw new Error('Context, temporal scope and rationale are required.');
  if(draft.basis_evidence_id&&!evidence.some(e=>e.evidence_id===draft.basis_evidence_id))throw new Error('Select a visible evidence fragment.');
  if(draft.dimension==='EVIDENCE_SUPPORTED_KNOWLEDGE'&&draft.judgment==='INDICATED'&&!draft.basis_evidence_id)throw new Error('Cite the evidence used for this judgment.');
  const body={...draft,target_object_id:draft.target_object_id||null,target_state_event_id:draft.target_state_event_id||null,target_actor_id:draft.target_actor_id||null,counterparty_actor_id:draft.counterparty_actor_id||null,influence_target:draft.influence_target||null,context:draft.context.trim(),temporal_scope:draft.temporal_scope.trim(),orientation_scope:draft.orientation_scope||null,orientation_goal:draft.orientation_goal?.trim()||null,rationale:draft.rationale.trim(),basis_evidence_id:draft.basis_evidence_id||null};
  if(body.revises_event_id){const prior=events.find(e=>e.event_id===body.revises_event_id);if(!prior||events.some(e=>e.input.revises_event_id===prior.event_id)||['subject_actor_id','target_object_id','target_state_event_id','target_actor_id','counterparty_actor_id','influence_target','dimension','context','temporal_scope','orientation_scope','orientation_goal'].some(k=>(prior.input[k]??null)!==body[k]))throw new Error('Revision must preserve the current state identity.');}
  return body;
}

export function ActorEpistemicStatePanel({snapshot,actors,client,onChanged}) {
  const [draft,setDraft]=useState(empty);
  const [saving,setSaving]=useState(false);
  const [error,setError]=useState('');
  const pending=useRef(null);
  const nodes=snapshot.nodes??[], evidence=snapshot.evidence??[], events=snapshot.actor_epistemic_states??[];
  const revised=new Set(events.map(e=>e.input.revises_event_id));
  const actorById=new Map(actors.map(a=>[a.actor_id,a])),nodeById=new Map(nodes.map(n=>[n.object_id,n])),eventById=new Map(events.map(e=>[e.event_id,e]));
  const actorLabel=id=>actorById.get(id)?.display_label??id;
  const stateLabel=e=>`${actorLabel(e.input.subject_actor_id)} — ${label(e.input.dimension)}: ${label(e.input.judgment)}${e.input.orientation_scope?` · ${label(e.input.orientation_scope)}`:''} (${e.event_id})${revised.has(e.event_id)?' — historically revised':''}`;
  const targetLabel=input=>(input.influence_target?`Influence target: ${label(input.influence_target)} · `:'')+(input.counterparty_actor_id?`Counterparty: ${actorLabel(input.counterparty_actor_id)} · `:'')+(input.target_actor_id?`Directed to actor: ${actorLabel(input.target_actor_id)}`:input.target_state_event_id?`State event: ${eventById.has(input.target_state_event_id)?stateLabel(eventById.get(input.target_state_event_id)):input.target_state_event_id}`:(nodeById.get(input.target_object_id)?.text??input.target_object_id));
  const change=(key,value)=>setDraft(d=>({...d,[key]:value}));
  const locked=!!draft.revises_event_id;
  async function save(e){e.preventDefault();if(saving)return;try{const body=stateRequest(draft,actors,nodes,evidence,events);const key=JSON.stringify(body);if(pending.current?.key!==key)pending.current={key,id:crypto.randomUUID()};setSaving(true);setError('');await client.recordActorEpistemicState(pending.current.id,body);pending.current=null;setDraft(empty);await onChanged();}catch(e){setError(e.message);}finally{setSaving(false);}}
  return <details><summary>Actor epistemic states — independent attributed judgments</summary><p>Exposure, access, attention, comprehension, belief and claimed knowledge are distinct. No state is inferred from another, and no recorded judgment establishes a fact about an actor’s mind. Only the original recorder can revise their judgment; other investigators can record a separate judgment.</p>
    {!actors.length&&<p>No registered actor available; no identity is inferred.</p>}
    <form onSubmit={save}><fieldset disabled={saving||!actors.length}><legend>{locked?'Revise an exact attributed judgment':'Record an attributed judgment'}</legend>
      <label>Actor<select required disabled={locked} value={draft.subject_actor_id} onChange={e=>change('subject_actor_id',e.target.value)}><option value="">Choose…</option>{actors.map(a=><option key={a.actor_id} value={a.actor_id}>{a.display_label}</option>)}</select></label>
      <label>Dimension<select required disabled={locked} value={draft.dimension} onChange={e=>setDraft(d=>({...d,dimension:e.target.value,target_object_id:null,target_state_event_id:null,target_actor_id:null,counterparty_actor_id:null,influence_target:null,judgment:'',orientation_scope:null,orientation_goal:null}))}><option value="">Choose…</option><optgroup label="Epistemic states">{stateDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Epistemic orientations">{orientationDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Directed trust and loyalty">{relationalDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Attributed protective motives">{protectiveMotiveDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Contextual autonomy">{autonomyDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Contextual pressure and dependency">{contextualPressureDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Qualified threat facets">{threatFacetDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Vulnerability and responses">{contextualVulnerabilityDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Epistemic influence">{influenceDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup><optgroup label="Epistemic power and directed asymmetry">{powerDimensions.map(d=><option key={d} value={d}>{label(d)}</option>)}</optgroup></select></label>
      {contextualPressureDimensions.includes(draft.dimension)&&<p>An incentive, communicated threat, adverse condition, coercion, constraint, dependency and leverage are different attributed conditions. None automatically establishes another, consent, intent or a legal conclusion.</p>}
      {threatFacetDimensions.includes(draft.dimension)&&<p>Capability and intent concern the alleged issuer; perceived credibility concerns the affected actor; outcome concerns what happened to the affected actor. Each judgment is independent and attributed, not a verified fact or causal finding.</p>}
      {contextualVulnerabilityDimensions.includes(draft.dimension)&&<p>Vulnerability is contextual exposure to an adverse consequence, not a personal flaw. Susceptibility, compliance, consent and submission remain independent; compliance does not establish consent and submission does not establish loyalty. These judgments do not confer system authorization.</p>}
      {influenceDimensions.includes(draft.dimension)&&<><p>Influence capacity, act, intended effect, actual effect and perceived success are separate attributed judgments. An act or formal position does not prove that an effect occurred.</p><label>Epistemic influence target<select required disabled={locked} value={draft.influence_target??''} onChange={e=>change('influence_target',e.target.value||null)}><option value="">Choose…</option>{influenceTargets.map(t=><option key={t} value={t}>{label(t)}</option>)}</select></label></>}
      {powerDimensions.includes(draft.dimension)&&<p>Epistemic power and formal authority are distinct. Asymmetry attributes a comparative advantage to the selected subject relative to the exact counterparty in this context; no reverse comparison, global rank or authorization is inferred.</p>}
      {counterpartyDimensions.includes(draft.dimension)&&<label>{asymmetryDimensions.includes(draft.dimension)?'Compared actor (required)':issuerRequiredDimensions.includes(draft.dimension)?'Attributed issuer or influencing actor (required)':'Attributed counterparty (optional)'}<select required={issuerRequiredDimensions.includes(draft.dimension)} disabled={locked} value={draft.counterparty_actor_id??''} onChange={e=>change('counterparty_actor_id',e.target.value||null)}><option value="">Not identified</option>{actors.filter(a=>a.actor_id!==draft.subject_actor_id).map(a=><option key={a.actor_id} value={a.actor_id}>{a.display_label}</option>)}</select></label>}
      {autonomyDimensions.includes(draft.dimension)&&<p>Ability to decide, refuse, disagree, exit, seek review, acquire information and revise commitments may differ independently. An attributed capability does not confer authorization or establish consent.</p>}
      {protectiveMotiveDimensions.includes(draft.dimension)&&<p>Ego protection concerns personal self-image or status. Identity protection concerns a broader identity, such as a professional or group identity. Neither is a personality diagnosis or inferred from behavior alone.</p>}
      {relationalDimensions.includes(draft.dimension)&&<p>Trust and loyalty are attributed relations, not system permissions, reliability ratings or proof of obedience. Dimensions remain independent.</p>}
      <label>Target<select required disabled={locked||!draft.dimension} value={draft.target_actor_id?`actor:${draft.target_actor_id}`:draft.target_state_event_id?`state:${draft.target_state_event_id}`:draft.target_object_id?`object:${draft.target_object_id}`:''} onChange={e=>{const [kind,id]=e.target.value.split(':');setDraft(d=>({...d,target_object_id:kind==='object'?id:null,target_state_event_id:kind==='state'?id:null,target_actor_id:kind==='actor'?id:null}));}}><option value="">Choose…</option>{!trustDimensions.includes(draft.dimension)&&<optgroup label="Objects">{nodes.map(n=><option key={n.object_id} value={`object:${n.object_id}`}>{n.text}</option>)}</optgroup>}{!relationalDimensions.includes(draft.dimension)&&!objectOnlyDimensions.includes(draft.dimension)&&<optgroup label="Prior attributed state events">{events.map(e=><option key={e.event_id} value={`state:${e.event_id}`}>{stateLabel(e)}</option>)}</optgroup>}{relationalDimensions.includes(draft.dimension)&&<optgroup label="Directed actor targets">{actors.map(a=><option key={a.actor_id} value={`actor:${a.actor_id}`}>{a.display_label}</option>)}</optgroup>}</select></label>
      {orientationDimensions.includes(draft.dimension)&&<fieldset><legend>Orientation qualification</legend><p>A reported reaction does not prove a persistent personality trait. Goal is an attributed description, not an inferred motive.</p><label>Scope<select required disabled={locked} value={draft.orientation_scope??''} onChange={e=>change('orientation_scope',e.target.value)}><option value="">Choose…</option>{orientationScopes.map(s=><option key={s} value={s}>{label(s)}</option>)}</select></label><label>Attributed goal<input required disabled={locked} maxLength={2048} value={draft.orientation_goal??''} onChange={e=>change('orientation_goal',e.target.value)}/></label></fieldset>}
      <label>Judgment<select required value={draft.judgment} onChange={e=>change('judgment',e.target.value)}><option value="">Choose…</option>{(trustDimensions.includes(draft.dimension)?[...judgments,'DISTRUST_INDICATED']:judgments).map(j=><option key={j} value={j}>{label(j)}</option>)}</select></label>
      <label>Context<input required disabled={locked} maxLength={2048} value={draft.context} onChange={e=>change('context',e.target.value)}/></label>
      <label>Temporal scope<input required disabled={locked} maxLength={2048} value={draft.temporal_scope} onChange={e=>change('temporal_scope',e.target.value)}/></label>
      <label>Rationale<textarea required maxLength={4096} value={draft.rationale} onChange={e=>change('rationale',e.target.value)}/></label>
      <label>Evidence fragment<select value={draft.basis_evidence_id} onChange={e=>change('basis_evidence_id',e.target.value)}><option value="">Not explicitly linked</option>{evidence.map(e=><option key={e.evidence_id} value={e.evidence_id}>{e.speaker_label}: {e.content?.slice(0,120)} ({e.evidence_id})</option>)}</select></label>
      <button type="submit">Record judgment only</button>{locked&&<button type="button" onClick={()=>setDraft(empty)}>Cancel revision</button>}{error&&<p role="alert">{error}</p>}
    </fieldset></form>
    <h4>Attributed state history</h4><p>A reference to another actor's state identifies the exact prior event; later revisions do not silently replace it or imply knowledge.</p>{!events.length?<p>No explicit state judgment recorded. Absence is not unknown or a negative judgment.</p>:<ul>{events.map(e=><li key={e.event_id}><strong>{actorLabel(e.input.subject_actor_id)} — {label(e.input.dimension)}: {label(e.input.judgment)}</strong><p>{targetLabel(e.input)} · {e.input.context} · {e.input.temporal_scope}</p>{e.input.orientation_scope&&<p>{label(e.input.orientation_scope)} · attributed goal: {e.input.orientation_goal}</p>}<p>{e.input.rationale}</p><small>By {e.recorded_by} · {e.recorded_at} · {e.event_id} · basis {e.input.basis_evidence_id??'not explicitly linked'}</small>{revised.has(e.event_id)?<p>Historical — explicitly revised.</p>:<button type="button" disabled={saving} onClick={()=>setDraft({...e.input,basis_evidence_id:e.input.basis_evidence_id??'',revises_event_id:e.event_id})}>Propose revision of this judgment</button>}</li>)}</ul>}
  </details>;
}
